import importlib.util,sqlite3,tempfile
from pathlib import Path
P=Path(__file__).parents[1]/'tools'/'disposition_parser.py'; spec=importlib.util.spec_from_file_location('dp',P); dp=importlib.util.module_from_spec(spec); spec.loader.exec_module(dp)
def db():
 c=sqlite3.connect(':memory:');c.row_factory=sqlite3.Row;c.executescript('''CREATE TABLE published_judgments(judgment_id TEXT PRIMARY KEY,case_title TEXT,citation TEXT,decision_date TEXT,court_level TEXT,source_url TEXT,retrieved_at TEXT,raw_metadata TEXT,decision_text TEXT,summary TEXT,outcome_type TEXT,verification_state TEXT,sentence_text TEXT);CREATE TABLE cases(case_id TEXT PRIMARY KEY,case_title TEXT,citation TEXT,court_level TEXT,opened_date TEXT,closed_date TEXT,legal_status TEXT,final_outcome TEXT,verification_state TEXT,source_type TEXT,source_url TEXT,retrieved_at TEXT,notes TEXT);CREATE TABLE people(person_id TEXT PRIMARY KEY,display_name TEXT);CREATE TABLE case_people(case_id TEXT,person_id TEXT,role TEXT,verification_state TEXT,UNIQUE(case_id,person_id));CREATE TABLE person_mentions(person_id TEXT,source_entity_id TEXT);CREATE TABLE charges(charge_id TEXT PRIMARY KEY,case_id TEXT,offence_text TEXT,charge_status TEXT,disposition TEXT,disposition_date TEXT,verification_state TEXT,source_entity_id TEXT);CREATE TABLE review_queue(review_id TEXT PRIMARY KEY,entity_type TEXT,entity_id TEXT,reason TEXT,priority TEXT,status TEXT,created_at TEXT);''');return c
def test_explicit_conviction_creates_verified_outcome():
 c=db();c.execute("INSERT INTO people VALUES('p1','Tony Smith')");c.execute("INSERT INTO published_judgments VALUES('j1','R. v. Tony Smith','2026 BCPC 1','2026-01-02','BCPC','u','now','','The accused pleaded guilty to assault. He was sentenced for the conviction.','','review','','')");c.execute("INSERT INTO person_mentions VALUES('p1','j1')");r=dp.run(c);assert r['convictions']==1;assert tuple(c.execute("SELECT outcome_type,verified FROM outcomes").fetchone())==('convicted',1)
def test_not_guilty_does_not_create_conviction():
 c=db();c.execute("INSERT INTO published_judgments VALUES('j2','R. v. A.B.','','2026-01-02','BCPC','u','now','','The accused was found not guilty and acquitted.','','review','','')");r=dp.run(c);assert r['convictions']==0;assert c.execute('SELECT COUNT(*) FROM outcomes').fetchone()[0]==0
